<template>
  <div class="settings-page">
    <PageTitle eyebrow="SETTINGS" title="设置" />
    <div class="settings-layout"><aside class="settings-summary surface"><div class="summary-avatar">{{ avatarLetter }}</div><h2>{{ username }}</h2><p>{{ direction || '还没有设置学习方向' }}</p><div class="summary-rule"></div><span class="summary-label">本地偏好</span><strong>{{ enabledPreferenceCount }} 项已开启</strong></aside><div class="settings-sections">
      <section class="settings-section surface"><div class="settings-section-heading"><div><p class="eyebrow">LEARNING DIRECTION</p><h2>当前学习方向</h2></div><Compass :size="19" /></div><div class="direction-card"><div><span class="direction-label">当前画像</span><strong>{{ direction || '尚未选择' }}</strong></div><RouterLink class="button button--quiet" to="/onboarding/direction">重新定向 <ArrowUpRight :size="14" /></RouterLink></div></section>
      <section class="settings-section surface"><div class="settings-section-heading"><div><p class="eyebrow">LEARNING RHYTHM</p><h2>学习提醒</h2></div><Bell :size="19" /></div><div class="setting-row"><div><strong>每日学习提醒</strong></div><button class="switch" type="button" role="switch" :aria-checked="settings.reminder" :class="{ 'is-on': settings.reminder }" @click="settings.reminder = !settings.reminder"><span></span></button></div><div class="setting-row setting-row--select"><div><strong>提醒时间</strong></div><select v-model="settings.reminderTime" :disabled="!settings.reminder"><option>08:30</option><option>12:30</option><option>18:30</option><option>21:00</option></select></div></section>
      <section class="settings-section surface"><div class="settings-section-heading"><div><p class="eyebrow">ACCOUNT</p><h2>账户信息</h2></div><UserRound :size="19" /></div><div class="account-grid"><div><span>用户名</span><strong>{{ username }}</strong></div><div><span>邮箱</span><strong>{{ email || '未绑定邮箱' }}</strong></div></div><RouterLink class="text-link" to="/profile">管理个人资料 <ArrowRight :size="14" /></RouterLink></section>
      <section class="settings-section surface"><div class="settings-section-heading"><div><p class="eyebrow">PRIVACY</p><h2>账户与隐私</h2></div><ShieldCheck :size="19" /></div><div class="setting-row"><div><strong>个性化推荐</strong></div><button class="switch" type="button" role="switch" :aria-checked="settings.personalization" :class="{ 'is-on': settings.personalization }" @click="settings.personalization = !settings.personalization"><span></span></button></div><div class="setting-row"><div><strong>保留本地草稿</strong></div><button class="switch" type="button" role="switch" :aria-checked="settings.keepDrafts" :class="{ 'is-on': settings.keepDrafts }" @click="settings.keepDrafts = !settings.keepDrafts"><span></span></button></div><div class="privacy-actions"><button class="button button--quiet" type="button" @click="clearDrafts"><Trash2 :size="14" />清除本地草稿</button><span v-if="notice" class="save-notice">{{ notice }}</span></div></section>
    </div></div>
  </div>
</template>

<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { ArrowRight, ArrowUpRight, Bell, Compass, ShieldCheck, Trash2, UserRound } from 'lucide-vue-next'
import PageTitle from '@/shared/ui/PageTitle.vue'
import { authApi } from '@/shared/api/authApi'

const username = ref(localStorage.getItem('learnmate_username') || '我的学习者'); const email = ref(''); const direction = ref(localStorage.getItem('learnmate_direction') || ''); const goal = ref(localStorage.getItem('learnmate_goal') || ''); const notice = ref('')
const settings = reactive({ reminder: localStorage.getItem('learnmate_reminder') !== 'off', reminderTime: localStorage.getItem('learnmate_reminder_time') || '18:30', personalization: localStorage.getItem('learnmate_personalization') !== 'off', keepDrafts: localStorage.getItem('learnmate_keep_drafts') !== 'off' })
const avatarLetter = computed(() => username.value.trim().slice(0, 1).toUpperCase() || '学'); const enabledPreferenceCount = computed(() => [settings.reminder, settings.personalization, settings.keepDrafts].filter(Boolean).length)
function persistSettings() { localStorage.setItem('learnmate_reminder', settings.reminder ? 'on' : 'off'); localStorage.setItem('learnmate_reminder_time', settings.reminderTime); localStorage.setItem('learnmate_personalization', settings.personalization ? 'on' : 'off'); localStorage.setItem('learnmate_keep_drafts', settings.keepDrafts ? 'on' : 'off'); notice.value = '已保存'; window.setTimeout(() => { notice.value = '' }, 1800) }
function clearDrafts() { Object.keys(localStorage).filter((key) => key.startsWith('learnmate_draft_')).forEach((key) => localStorage.removeItem(key)); notice.value = '本地草稿已清除'; window.setTimeout(() => { notice.value = '' }, 2200) }
watch(settings, persistSettings, { deep: true })
onMounted(async () => { try { const user = await authApi.readUser(); username.value = user.username || username.value; email.value = user.email || '' } catch { /* 登录态由路由守卫处理 */ } })
</script>

