ding: 2px; border: 0; border-radius: 99px; background: #d6ddd6; transition: background .2s ease; }.switch span { display: block; width: 19px; height: 19px; border-radius: 50%; background: #fff; box-shadow: 0 1px 3px rgba(0,0,0,.18); transition: transform .2s ease; }.switch.is-on { background: var(--accent-deep); }.switch.is-on span { transform: translateX(16px); }.setting-row--select select { min-height: 33px; padding: 0 9px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper); color: var(--ink); font-size: 12px; }.direction-card { display: flex; align-items: center; justify-content: space-between; gap: 18px; margin-top: 16px; padding: 15px; border: 1px solid rgba(63,65,70,.12); border-radius: 6px; background: rgba(250,255,196,.18); }.direction-label { display: block; margin-bottom: 6px; color: var(--muted); font-size: 10px; }.direction-card strong { display: block; font-size: 15px; }.direction-card p { margin: 5px 0 0; color: var(--muted); font-size: 12px; }.direction-card .button { flex: 0 0 auto; gap: 5px; min-height: 35px; padding: 0 10px; font-size: 11px; }.account-grid { display: grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap: 10px; margin: 16px 0 14px; }.account-grid div { display: grid; gap: 5px; padding: 13px; border: 1px solid var(--line); border-radius: 5px; }.account-grid span { color: var(--muted); font-size: 10px; }.account-grid strong { overflow: hidden; font-size: 13px; text-overflow: ellipsis; }.text-link { display: inline-flex; align-items: center; gap: 5px; color: var(--accent-deep); font-size: 11px; font-weight: 800; text-decoration: none; }.privacy-actions { display: flex; align-items: center; gap: 12px; margin-top: 14px; }.privacy-actions .button { display: inline-flex; align-items: center; gap: 6px; min-height: 35px; font-size: 11px; }.save-notice { color: var(--accent-deep); font-size: 11px; }
@media (max-width: 760px) { .settings-layout { grid-template-columns: 1fr; }.settings-summary { position: static; }.settings-summary p { white-space: normal; }.settings-page :deep(.page-heading h1) { font-size: 25px; } } @media (max-width: 500px) { .settings-section { padding: 16px; }.direction-card { align-items: flex-start; flex-direction: column; }.direction-card .button { width: 100%; }.account-grid { grid-template-columns: 1fr; }.setting-row { min-height: 68px; } }
